import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.C0pL2NcE.js";const g=JSON.parse('{"title":"Deployment","description":"","frontmatter":{},"headers":[],"relativePath":"guide/deployment.md","filePath":"guide/deployment.md"}'),n={name:"guide/deployment.md"};function o(l,e,r,d,h,p){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h1><p>The site is built <strong>on your machine</strong> and pushed to the <code>gh-pages</code> branch. GitHub Pages serves that branch as-is (Settings → Pages → <em>Deploy from a branch</em>: <code>gh-pages</code>, <code>/</code>). There is no deploy workflow.</p><table tabindex="0"><thead><tr><th>Path</th><th>Content</th></tr></thead><tbody><tr><td><a href="https://tuandds.github.io/colony-flow-sand/" target="_blank" rel="noreferrer"><code>/colony-flow-sand/</code></a></td><td>Landing page with the list of all versions</td></tr><tr><td><a href="https://tuandds.github.io/colony-flow-sand/demo/" target="_blank" rel="noreferrer"><code>/colony-flow-sand/demo/</code></a></td><td>Latest game build</td></tr><tr><td><a href="https://tuandds.github.io/colony-flow-sand/docs/" target="_blank" rel="noreferrer"><code>/colony-flow-sand/docs/</code></a></td><td>Latest documentation</td></tr><tr><td><code>/colony-flow-sand/vX.Y.Z/demo/</code>, <code>/vX.Y.Z/docs/</code></td><td>A frozen release</td></tr></tbody></table><h2 id="updating-latest" tabindex="-1">Updating latest <a class="header-anchor" href="#updating-latest" aria-label="Permalink to &quot;Updating latest&quot;">​</a></h2><p>Pushing to <code>main</code> does <strong>not</strong> update the live site by itself. After pushing, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release:latest</span></span></code></pre></div><p>This requires being on <code>main</code>, in sync with <code>origin/main</code>, so latest always matches GitHub.</p><h2 id="releasing-a-version" tabindex="-1">Releasing a version <a class="header-anchor" href="#releasing-a-version" aria-label="Permalink to &quot;Releasing a version&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> minor</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # or patch / major: bumps package.json, commits, creates tag vX.Y.Z</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # optional: share the version bump on main</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # publishes v&lt;package.json version&gt; under /vX.Y.Z/ and pushes the tag</span></span></code></pre></div><p>You can also name the version: <code>npm run release -- v0.3.0-beta.1</code>. The script creates the tag if it doesn&#39;t exist. Republishing an existing tag requires checking out the commit it points to.</p><p>Both commands refuse to run with uncommitted changes, so every release matches a commit. Pages updates about a minute after the push.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p><code>scripts/release.sh</code>:</p><ol><li>Checks out <code>gh-pages</code> as a git worktree in <code>.pages/</code> (ignored by git), reset to <code>origin/gh-pages</code>. Your current branch is never touched.</li><li>Runs <code>scripts/publish-site.sh &lt;latest|vX.Y.Z&gt; .pages</code>. That builds the game and docs with the right base path and version label, writes them to the archive root (latest) or <code>.pages/vX.Y.Z/</code>, and regenerates <code>versions.json</code>. Other versions are left alone.</li><li>Adds <code>.nojekyll</code>, commits, and pushes <code>gh-pages</code>. For versions it also tags the commit and pushes the tag.</li></ol><p>The game menu shows the version it was built as (bottom-right corner), and the docs have a version menu in the top bar.</p><p>To remove a version, delete its folder in <code>.pages/</code>, then commit and push <code>gh-pages</code> (or run <code>npm run release:latest</code> afterwards to rebuild <code>versions.json</code>).</p><h2 id="previewing-locally" tabindex="-1">Previewing locally <a class="header-anchor" href="#previewing-locally" aria-label="Permalink to &quot;Previewing locally&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:site</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # latest site only, into _site/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --outDir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> _site</span></span></code></pre></div>`,18)])])}const k=s(n,[["render",o]]);export{g as __pageData,k as default};
